tool_input.command:
$env:PYTHONIOENCODING='utf-8'
$b='C:\Program Files\Python310\lib\site-packages\cnequity\steps'
foreach($pair in @('fundamentals.py','structure.py','reference.py','macro_risk.py')){
  Write-Output "===== $pair 主源关键字 ====="
  Select-String -Path "$b\$pair" -Pattern 'fetch_financial|fetch_industry_members|fetch_instrument_basics|fetch_trading_status|fetch_share_unlock|eastmoney|sw\.|cninfo|baostock|ths_official' | Select-Object -First 8 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(95,$_.Line.Trim().Length)))"}
}
Write-Output "===== 银行/治理源头(external_lake/ownership) ====="
Select-String -Path 'D:\repository\数据湖\分析产出\update_external_lake.py' -Pattern 'RPT_F10|datacenter|eastmoney' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(90,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "===== 1) 财务 PIT：筛选/取数是否用 announce_date/available_at 过滤 ====="
Select-String -Path 'D:\repository\数据湖\分析产出\screen_sh.py','D:\repository\数据湖\分析产出\screen_sz.py' -Pattern 'announce_date|available_at|report_period|as_of|基准日|base' | Select-Object -First 15 | ForEach-Object {"$($_.Filename):$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(95,$_.Line.Trim().Length)))"}
Write-Output ""
Write-Output "===== 2) 落库行数/时间戳防呆：data_sufficiency / 更新脚本 断言 ====="
Select-String -Path 'D:\repository\数据湖\分析产出\data_sufficiency.py' -Pattern 'assert|raise|len|行数|count|min|>=|threshold|完整性' | Select-Object -First 15 | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(95,$_.Line.Trim().Length)))"}
